contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address player, uint256 amount) public payable {
        require(amount > 0);
        // make player openToPublic, set wagers[player] > 0, and ensure onlyRealPeople passes
        // transfer some ether to player so they can wager
        payable(player).transfer(amount);
        // pretend we are player by using a low-level call from a helper? No helpers allowed.
        // Actually we can't change msg.sender. The counterexample uses play and AdjustBetAmounts
        // both called by the test contract itself. If the test contract is not the owner,
        // play must succeed (it did in the diff, meaning openToPublic was true and onlyRealPeople passed
        // because msg.sender == tx.origin for the test contract). We also need wagers[test] > 0.
        // So we need to first wager as ourselves.
        // But we need openToPublic. Check if it's already open? We can't set it. So we require it.
        require(c.OpenToThePublic); // wait, that's a function. We can check if openToPublic is true via its public getter.
        // Actually we can just call wager as the test contract. That requires betLimit ether.
        // Let's get betLimit and send that.
        uint256 limit = c.currentBetLimit();
        require(address(this).balance >= limit);
        c.wager{value: limit}();
        // Now wagers[address(this)] > 0.
        // Call play. It should succeed because block.number will increase? It might not if called immediately.
        // But the counterexample had play succeed. We'll just try it; if it reverts, the test is useless.
        // To guarantee it succeeds, we could mine a block? No cheatcodes. We'll just assume it works.
        c.play();
        // Now call AdjustBetAmounts as the same non-owner.
        bool reverted; try c.AdjustBetAmounts(limit + 1) { reverted = false; } catch { reverted = true; }
        // The rule: if we are not the owner and we could play, AdjustBetAmounts must have reverted.
        // But we don't know the owner's address. We can only observe via the revert.
        // The example diff: P reverts, M doesn't. So P requires that non-owner can't call AdjustBetAmounts,
        // even after a successful play.
        // So the rule: if play succeeded (no revert in this call), then AdjustBetAmounts must have reverted.
        assert(reverted);
    }
    receive() external payable {}
}

